insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('15641b26-b6eb-5afc-acd9-907b7ad61531','6ab64c65f01ec4542ab66a68','תל חדיד → מצפה מודיעין','המשך מקטע 21 — מתל חדיד דרומה לכיוון מצפה מודיעין. יום משפחתי/פיצול עם נקודת יציאה מאומתת לצעירים.','תל חדיד / בן שמן','2027-01-02','2027-01-02','confirmed','planned','regular','כ־35 דק׳ מתל אביב',8.0,'קל','','המשך מקטע 21. סיום במצפה מודיעין רק אם תוואי השביל המאומת תומך בכך.','',false,'','','','','','');
insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('aae64755-c907-593d-9422-3906829a3e11','6ab64c654fccf1c132a2a7e4','יער שוהם → תל חדיד','מקטע 21 (חלקי) — הליכה ביער שוהם ובסביבת תל חדיד. יום משפחתי/פיצול: הצעירים יוצאים מנקודת איסוף מאומתת.','שוהם / תל חדיד','2026-12-19','2026-12-19','confirmed','planned','regular','כ־30 דק׳ מתל אביב',9.0,'קל','','זהו רק חלק ממקטע 21 הרשמי — אין לסמן את המקטע כולו כהושלם.','',false,'','','','','','');
insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('e51d8621-2ae9-51de-8171-c16d0f017ad2','6ab64c654dc353d34d0f94e1','ממשיכים ללטרון','המשך מקטע 22 — משלימים את החלק שנותר לכיוון לטרון בקצב נעים. המרחק יחושב מהחלק שנותר לאחר הטיול הקודם.','מודיעין / לטרון','2027-01-30','2027-01-30','confirmed','planned','regular','כ־45 דק׳ מתל אביב',null,'קל','','אין מעבר מים. מרחק השביל הראשי ייקבע לפי החלק שנותר בפועל — אין לכפות יעד ק״מ. אם השלמת מקטע 22 תיצור יום לא סביר — להשאירו חלקי.','',false,'','','','','','');
insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('e0235adf-db8c-5abd-995a-50a9893fb89a','6ab64c65356711ebe8825414','מצפה מודיעין → המשך לכיוון לטרון','מקטע 22 (חלקי) — יום פיצול. השביל הצעיר הולך יחד 5–7 ק״מ, ואז הורה אחד יוצא עם הילד/ה הצעיר/ה בנקודת איסוף מאומתת.','בן שמן / מודיעין','2027-01-16','2027-01-16','confirmed','planned','regular','כ־45 דק׳ מתל אביב',11.0,'בינוני','','אין מעבר מים. נדרשת נקודת איסוף מאומתת עם גישה נוחה ברכב — לא להמציא נקודה.','',false,'','','','','','');
insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('0244ee33-e172-507a-9c53-dce7ce98cf18','6ab64c647c1d3be1b6e09d8b','פותחים את המסע — שביל האחוזה ברמת הנדיב','הטיול הראשון שלנו! מסלול מעגלי בשביל האחוזה (המסלול האדום) ברמת הנדיב — חורש ים־תיכוני, חורבת עקב ונוף אל הים. כ־4 ק״מ בקצב משפחתי, וחלק מהמסלול חופף לשביל ישראל.','רמת הנדיב / כרמל','2026-10-03','2026-10-03','confirmed','completed','regular','כ־55 דק׳ מתל אביב',4.0,'בינוני','','מסלול חשוף ברובו — כובע ומים חובה. אין להדליק אש בשטח הפארק ואין לינה; יש לסיים את הטיול לפני חשכה ולנוע רק בשבילים מסומנים. המורד מחורבת עקב לערוץ נחל תמסח עלול להיות חלק לאחר גשמים.','רגע פתיחה משפחתי וקטן: תמונה משפחתית בתחילת המסלול · תמונה ראשונה עם סימון שביל ישראל · שיחה קצרה — ׳למה אנחנו יוצאים למסע הזה?׳ · פתיחת יומן המסע · סימון הקילומטרים הראשונים שבוצעו בפועל.',true,'הכלבה חייבת להישאר ברצועה בשטח פארק הטבע, ואין לעבור דרך גני הזיכרון — שם אסורה כניסת כלבים.','','','','','');
insert into trips (id,legacy_id,title,summary,region,start_date,end_date,date_status,status,kind,drive_time,total_km_hint,difficulty,cover_url,notes,family_activity,dog_allowed,dog_notes,weather_note,area_closures,flood_alert,route_changes,recap) values ('2f81e6ab-b417-52bc-9deb-130fba08aa0d','6a9dc4e6d5a317097e8ab91e','הר יהורם ← אילת','אירוע הסיום הרשמי של המסע באילת.','אילת','2027-11-13','2027-11-13','confirmed','planned','mitzvah','כ־4 שעות',null,'','','','',null,'','','','','','');
