insert into trip_days (id,legacy_id,trip_id,date,day_number,segment_number,kind,title,start_name,start_url,end_name,end_url,distance_km,trail_km,partial_route,duration_text,difficulty,ascent_m,descent_m,route_type,route_description,route_map_url,main_participants,sun_exposure,water_liters,water_guidance,water_crossing,max_water_depth,escape_points,safety_notes,gear,shuttle_required,shuttle_details,parking_notes,drive_minutes,young_enabled,young_title,young_type,young_start,young_end,young_km,young_route_type,young_duration,young_difficulty,young_meetup,young_notes,verification,verification_source,verification_url,completion,completed_km,completion_note) values ('63ef6f81-df75-58eb-bdc2-8f8c90ca0745','6ab64c6571cfca42d2c1021a','0244ee33-e172-507a-9c53-dce7ce98cf18','2026-10-03',1,null,'family','פותחים את המסע — שביל האחוזה ברמת הנדיב','כיכר ראשית השבילים, רמת הנדיב','https://www.google.com/maps/search/?api=1&query=Ramat+Hanadiv','כיכר ראשית השבילים, רמת הנדיב','https://www.google.com/maps/search/?api=1&query=Ramat+Hanadiv',4.0,null,false,'2–3 שעות בקצב משפחתי','בינוני',null,null,'circular','שביל האחוזה (המסלול האדום, סימון אדום־לבן־אדום) יוצא מכיכר ראשית השבילים אל חורש ים־תיכוני ואחו פתוח, ומטפס לחורבת עקב — שרידי אחוזה ביזנטית בנקודה הגבוהה ברמת הנדיב (141 מ׳), עם גת, בית בד וגורן ונוף אל מישור חוף הכרמל והים. משם יורד המסלול אל ערוץ נחל תמסח וחוזר במעגל לנקודת המוצא. בתחילת השביל מלווה אותנו גם סימון שביל ישראל.','','','מלאה',2.0,'','','none','','מסלול חשוף ברובו — כובע, מים וקרם הגנה. המורד מחורבת עקב לערוץ נחל תמסח עלול להיות חלק לאחר גשמים. אין להדליק אש בשטח הפארק, אין לינה, ויש לסיים את הטיול לפני חשכה.','מגדיר פרחים, משקפת (ניתן לשכור בחנות המידע)',null,'','חניון פארק הטבע ליד כיכר ראשית השבילים. אין לינה בשטח הפארק.
